def test_action_is_written_on_the_shape_keys():
    obj = _mesh_with_shape_keys("mocap_action_test", ["jawOpen", "eyeBlinkLeft"])
    key = obj.data.shape_keys
    values = np.array([[0.0, 1.0], [0.5, 0.0], [1.0, 0.25]])
    action = MocapAnimationService.write_shape_key_action(key, "MPFB_Face_test", 10, ["jawOpen", "eyeBlinkLeft", "tongueOut"],
                                                          np.column_stack([values, np.zeros(3)]))
    try:
        assert key.animation_data.action == action
        assert action.use_fake_user
        scene = bpy.context.scene
        for row, frame in enumerate((10, 11, 12)):
            scene.frame_set(frame)
            assert key.key_blocks["jawOpen"].value == pytest.approx(values[row, 0], abs=1e-4)
            assert key.key_blocks["eyeBlinkLeft"].value == pytest.approx(values[row, 1], abs=1e-4)
    finally:
        _remove(obj)
        bpy.data.actions.remove(action)


def test_fitted_meshes_get_drivers(monkeypatch):
    basemesh = _mesh_with_shape_keys("mocap_driver_base", ["jawOpen", "eyeBlinkLeft"])
    child = _mesh_with_shape_keys("mocap_driver_child", ["jawOpen"])
    monkeypatch.setattr(MocapAnimationService, "fitted_children", staticmethod(lambda _basemesh: [child]))
    try:
        assert MocapAnimationService.drive_children(basemesh, ["jawOpen", "eyeBlinkLeft"]) == 1
        drivers = child.data.shape_keys.animation_data.drivers
        fcurve = drivers.find('key_blocks["jawOpen"].value')
        target = fcurve.driver.variables[0].targets[0]
        assert target.id == basemesh.data.shape_keys
        assert target.data_path == 'key_blocks["jawOpen"].value'
        # A second run does not add the drivers again
        assert MocapAnimationService.drive_children(basemesh, ["jawOpen"]) == 1
        assert len(drivers) == 1
    finally:
        _remove(child, basemesh)


def test_face_animation_on_a_character(tmp_path):
    if not FaceService.is_faceunits01_installed():
        pytest.skip("faceunits01 is not installed")
    basemesh = HumanService.create_human()
    scene = bpy.context.scene
    scene.frame_current = 5
    path = _write_face_source(tmp_path / "video1_clip_landmarks.npz")
    result = MocapAnimationService.create_face_animation(basemesh, path, {"include_children": False}, scene, "clip.mp4")
    action = bpy.data.actions[result["action"]]
    try:
        assert result["action"].startswith("MPFB_Face_clip")
        assert result["animated"] == 3
        assert result["frame_start"] == 5
        assert scene.frame_end >= result["frame_end"]
        animation_data = basemesh.data.shape_keys.animation_data
        assert animation_data.action is None
        track = animation_data.nla_tracks[_MODULE.FACE_TRACK]
        assert track.strips[0].action == action
        assert track.strips[0].frame_start == 5
    finally:
        bpy.data.actions.remove(action)


