def _layered_mesh():
    """A mesh with a face layer (jawOpen 0.5) and a lipsync layer (viseme_aa 1.0) on NLA tracks."""
    obj = _mesh_with_shape_keys("mocap_layers_test", ["jawOpen", "viseme_aa"])
    key = obj.data.shape_keys
    face = MocapAnimationService.write_shape_key_action(key, "MPFB_Face_test", 1, ["jawOpen"], np.full((10, 1), 0.5))
    MocapAnimationService.place_on_track(key, face, _MODULE.FACE_TRACK, 1, 10)
    lipsync = MocapAnimationService.write_shape_key_action(key, "MPFB_Lipsync_test", 3, ["viseme_aa"], np.ones((4, 1)))
    MocapAnimationService.place_on_track(key, lipsync, _MODULE.LIPSYNC_TRACK, 3, 6)
    return obj, [face, lipsync]


def test_layers_are_separate_nla_tracks():
    obj, actions = _layered_mesh()
    key = obj.data.shape_keys
    try:
        assert key.animation_data.action is None
        assert [track.name for track in MocapAnimationService.layer_tracks(obj)] == [_MODULE.FACE_TRACK, _MODULE.LIPSYNC_TRACK]
        bpy.context.scene.frame_set(4)
        assert key.key_blocks["jawOpen"].value == pytest.approx(0.5, abs=1e-4)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(1.0, abs=1e-4)
        # A new lipsync over the same frames replaces the old strip
        again = MocapAnimationService.write_shape_key_action(key, "MPFB_Lipsync_again", 4, ["viseme_aa"], np.ones((2, 1)))
        actions.append(again)
        MocapAnimationService.place_on_track(key, again, _MODULE.LIPSYNC_TRACK, 4, 5)
        assert [strip.action for strip in key.animation_data.nla_tracks[_MODULE.LIPSYNC_TRACK].strips] == [again]
    finally:
        _remove(obj)
        for action in actions:
            bpy.data.actions.remove(action)


def test_layers_bake_into_one_action():
    obj, actions = _layered_mesh()
    key = obj.data.shape_keys
    try:
        result = MocapAnimationService.bake_layers(obj)
        baked = bpy.data.actions[result["action"]]
        actions.append(baked)
        assert key.animation_data.action == baked
        assert all(track.mute for track in MocapAnimationService.layer_tracks(obj))
        assert (result["frame_start"], result["frame_end"]) == (1, 10)
        scene = bpy.context.scene
        scene.frame_set(4)
        assert key.key_blocks["jawOpen"].value == pytest.approx(0.5, abs=1e-4)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(1.0, abs=1e-4)
        scene.frame_set(8)
        assert key.key_blocks["viseme_aa"].value == pytest.approx(0.0, abs=1e-4)
    finally:
        _remove(obj)
        for action in actions:
            bpy.data.actions.remove(action)


def test_sound_strip_is_placed_and_trimmed(tmp_path):
    path = str(tmp_path / "line.wav")
    with wave.open(path, "wb") as sound:
        sound.setnchannels(1)
        sound.setsampwidth(2)
        sound.setframerate(16000)
        sound.writeframes(b"".join(struct.pack("<h", int(8000 * math.sin(i / 10.0))) for i in range(16000 * 4)))
    scene = bpy.context.scene
    fps = scene.render.fps / scene.render.fps_base
    try:
        strip = MocapAnimationService.add_sound_strip(scene, path, "MPFB_Lipsync_line", 20, 1.0, int(2 * fps), fps)
    except RuntimeError as err:
        pytest.skip("No sound support in this blender: %s" % err)
    try:
        assert strip.frame_final_start == 20
        assert strip.frame_final_end == pytest.approx(20 + int(2 * fps), abs=1)
    finally:
        editor = scene.sequence_editor
        (editor.strips if hasattr(editor, "strips") else editor.sequences).remove(strip)


def test_livelink_csv_gives_face_curves(tmp_path):
    names = ["Timecode", "BlendShapeCount", "EyeBlinkLeft", "JawOpen", "TongueOut", "HeadYaw"]
    lines = [",".join(names)]
    for frame in range(60):
        lines.append("00:00:01:%02d.000,52,%.3f,0.5,0.2,0.1" % (frame, 1.0 if 20 <= frame < 26 else 0.0))
    path = tmp_path / "take.csv"
    path.write_text("\n".join(lines) + "\n", encoding="utf-8")
    curves = MocapAnimationService.prepare_face_curves(str(path), {"smoothing": 0.0}, 30.0)
    assert curves["names"] == ["eyeBlinkLeft", "jawOpen", "tongueOut"]
    assert curves["frames"] == 30
    assert np.allclose(curves["values"][:, 1], 0.5)
    assert curves["values"][:, 0].max() == pytest.approx(1.0)


# ------- Head rotation ---------

def test_rotation_vectors_round_trip():
    vectors = np.array([[0.0, 0.0, 0.0], [0.3, -0.2, 0.1], [0.0, 1.2, 0.0], [1e-8, 0.0, 0.0]])
    matrices = MocapAnimationService.vectors_to_matrices(vectors)
    assert np.allclose(matrices[2], _around("y", math.degrees(1.2)))
    assert np.allclose(MocapAnimationService.matrices_to_vectors(matrices), vectors, atol=1e-7)
    nan = MocapAnimationService.matrices_to_vectors(np.full((1, 3, 3), np.nan))
    assert np.isnan(nan).all()


def test_livelink_angles_turn_around_the_camera_axes():
    matrices = MocapAnimationService.euler_to_matrices(np.radians([[30.0, 0, 0], [0, 20.0, 0], [0, 0, 10.0]]))
    assert np.allclose(matrices[0], _around("y", 30))
    assert np.allclose(matrices[1], _around("x", 20))
    assert np.allclose(matrices[2], _around("z", 10))


def test_head_turning_to_the_right_of_the_image_turns_the_rig_to_its_left(tmp_path):
    # Seen from the camera, the head turns to the right of the image = to the character's left = +Z of the rig
    path = _write_face_source(tmp_path / "face.npz", head=_around("y", 30))
    curves = MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0}, 24.0)
    assert curves["frames"] == 120
    assert curves["start"] == pytest.approx(1.0)
    assert np.allclose(curves["rotations"], [0.0, 0.0, math.radians(30)], atol=1e-5)
    # Nodding down (chin towards the camera) is around the side axis of the rig
    path = _write_face_source(tmp_path / "nod.npz", head=_around("x", 15))
    assert np.allclose(MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0}, 24.0)["rotations"],
                       [math.radians(15), 0.0, 0.0], atol=1e-5)


def test_head_rotation_is_mirrored_and_relative_to_neutral(tmp_path):
    path = _write_face_source(tmp_path / "face.npz", head=_around("y", 30) @ _around("x", 10))
    mirrored = MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0, "mirror": True}, 30.0)
    plain = MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0}, 30.0)
    assert np.allclose(mirrored["rotations"], plain["rotations"] * [1.0, -1.0, -1.0], atol=1e-6)
    neutral = MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0, "use_neutral": True, "neutral_time": 1.0}, 30.0)
    assert np.allclose(neutral["rotations"], 0.0, atol=1e-6)


def test_head_gaps_are_filled(tmp_path):
    path = _write_face_source(tmp_path / "face.npz", head=_around("y", -20), gaps=[(40, 45), (80, 150)])
    rotations = MocapAnimationService.prepare_head_curves(path, {"smoothing": 0.0}, 30.0)["rotations"]
    assert not np.isnan(rotations).any()
    assert rotations[42, 2] == pytest.approx(math.radians(-20), abs=1e-5)  # short gap interpolated
    assert rotations[140, 2] == 0.0                                       # long gap back to neutral
    assert rotations[82, 2] < 0.0                                         # signed fade, not cut to 0


